import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:flex_notizbuch/domain/models.dart';
import 'package:flex_notizbuch/security/backup_codec.dart';

void main() {
  test(
    'decrypts synthetic envelope generated by original HTML Web Crypto functions in Node',
    () async {
      final decoded = await BackupCodec.decrypt(
        File('test/fixtures/html_encrypted.json').readAsStringSync(),
        'Testpasswort 123!',
      );
      expect(jsonDecode(decoded), {
        'synthetic': true,
        'text': 'Synthetischer Inhalt ÄÖÜ',
      });
    },
  );
  test(
    'encryption roundtrip uses fresh salt and IV and preserves Unicode password spaces',
    () async {
      const plain = '{"synthetic":"ÄÖÜ","records":[]}',
          password = '  Synthetisches Passwort Ä  ';
      final first = await BackupCodec.encrypt(plain, password),
          second = await BackupCodec.encrypt(plain, password);
      expect(first, isNot(second));
      expect(await BackupCodec.decrypt(first, password), plain);
      await expectLater(
        BackupCodec.decrypt(first, password.trim()),
        throwsA(isA<DomainError>()),
      );
    },
  );
  test('modified ciphertext is rejected before reading plaintext', () async {
    final envelope =
        jsonDecode(File('test/fixtures/html_encrypted.json').readAsStringSync())
            as Json;
    final bytes = base64Decode(envelope['ciphertext'] as String);
    bytes[0] ^= 1;
    envelope['ciphertext'] = base64Encode(bytes);
    await expectLater(
      BackupCodec.decrypt(jsonEncode(envelope), 'Testpasswort 123!'),
      throwsA(isA<DomainError>()),
    );
  });
  test('invalid parameters and short passwords are rejected', () async {
    final original =
        jsonDecode(File('test/fixtures/html_encrypted.json').readAsStringSync())
            as Json;
    for (final change in <Json>[
      {'iterations': 1},
      {'version': 2},
      {'salt': 'AA=='},
      {'iv': 'AA=='},
      {'ciphertext': 'AA=='},
    ]) {
      await expectLater(
        BackupCodec.decrypt(
          jsonEncode({...original, ...change}),
          'Testpasswort 123!',
        ),
        throwsA(isA<DomainError>()),
      );
    }
    await expectLater(
      BackupCodec.encrypt('{}', 'kurz'),
      throwsA(isA<DomainError>()),
    );
  });
}
